import java.util.*;

public class Main {
    int[] countBits(int n) {
        int[] ans = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            int count = 0;
            int x = i;
            while (x != 0) {                                          // recomputes the bit count from scratch for every i
                x &= (x - 1);
                count++;
            }
            ans[i] = count;
        }
        return ans;
    }

    public static void main(String[] args) {
        int n = 5;
        Main solution = new Main();
        System.out.println(Arrays.toString(solution.countBits(n)));
    }
}

