def count_bits(n):
    ans = [0] * (n + 1)
    for i in range(1, n + 1):
        ans[i] = ans[i >> 1] + (i & 1)                          # reuse the answer already computed for i shifted right
    return ans


if __name__ == "__main__":
    n = 5
    print(count_bits(n))

